//! B03 rendering and bound paths of `NewExprent`, `VarExprent` and `FieldExprent`
//! against vectors from the real Vineflower 1.12.0 classes
//! (`data/b03/GenB03Oracle.java` -> `data/b03/b03_golden.txt`, regenerated by
//! `data/b03/gen.sh`). Each scenario builds its exprents in the driver's order.

use kuna_jvm::check_types_result::{CheckTypesResult, ExprentTypePair};
use kuna_jvm::code_type::CodeType;
use kuna_jvm::const_exprent::ConstExprent;
use kuna_jvm::counter_container::CounterContainer;
use kuna_jvm::decompiler_context::DecompilerContext;
use kuna_jvm::exprent::Exprent;
use kuna_jvm::field_descriptor::FieldDescriptor;
use kuna_jvm::field_exprent::FieldExprent;
use kuna_jvm::new_exprent::NewExprent;
use kuna_jvm::var_exprent::VarExprent;
use kuna_jvm::var_type::VarType;

use crate::common;

const GOLDEN: &str = include_str!("data/b03/b03_golden.txt");

fn reset() {
    DecompilerContext::get_counter_container().set_counter(CounterContainer::EXPRESSION_COUNTER, 1);
}

fn hex(s: &str) -> String {
    let mut out = String::from("x");
    for u in s.encode_utf16() {
        out.push_str(&format!("{u:04x}"));
    }
    out
}

fn vt(t: &VarType) -> String {
    format!(
        "{}:{}:{}",
        t.type_.name(),
        t.array_dim,
        t.value.as_deref().unwrap_or("N")
    )
}

fn bounds(pairs: &[ExprentTypePair]) -> String {
    if pairs.is_empty() {
        return "-".to_string();
    }
    pairs
        .iter()
        .map(|p| format!("{}={}", p.exprent.get_id(), vt(&p.type_)))
        .collect::<Vec<_>>()
        .join(",")
}

fn text(e: Exprent) -> String {
    hex(&e.to_java(0).convert_to_string_and_allow_data_discard())
}

fn b(v: bool) -> &'static str {
    if v {
        "1"
    } else {
        "0"
    }
}

fn line(tag: &str, fields: &[String]) -> String {
    let mut s = tag.to_string();
    for f in fields {
        s.push(' ');
        s.push_str(f);
    }
    s
}

fn bounds_line(label: &str, r: &CheckTypesResult) -> String {
    line(
        "new_bounds",
        &[
            label.to_string(),
            bounds(r.get_lower_bounds()),
            bounds(r.get_upper_bounds()),
        ],
    )
}

fn class_descriptor() -> FieldDescriptor {
    FieldDescriptor::parse_descriptor("Ljava/lang/Class;")
}

#[test]
fn b03_exprents_match_vineflower() {
    let _guard = common::install_default_context();
    let mut actual: Vec<String> = Vec::new();

    for cls in [
        "java/lang/Boolean",
        "java/lang/Byte",
        "java/lang/Character",
        "java/lang/Short",
        "java/lang/Integer",
        "java/lang/Long",
        "java/lang/Float",
        "java/lang/Double",
        "java/lang/Void",
    ] {
        reset();
        let f = FieldExprent::new(
            "TYPE".to_string(),
            cls.to_string(),
            true,
            None,
            class_descriptor(),
            None,
        );
        actual.push(line("field_type", &[cls.to_string(), text(f.0)]));
    }

    reset();
    let condy = FieldExprent::new_full(
        "TYPE".to_string(),
        "java/lang/Long".to_string(),
        true,
        None,
        class_descriptor(),
        None,
        false,
        true,
    );
    actual.push(line("field_condy", &[text(condy.0)]));

    for (index, version) in [(5, 0), (5, 2), (0, 0), (10003, 7)] {
        reset();
        let v = VarExprent::new(index, Some(VarType::VARTYPE_INT()), None);
        v.set_version(version);
        let none = v.check_expr_type_bounds();
        v.set_bound_type(Some(VarType::VARTYPE_STRING()));
        let r = v.check_expr_type_bounds().expect("bound type set");
        actual.push(line(
            "var",
            &[
                index.to_string(),
                version.to_string(),
                text(v.0),
                v.get_name(),
                vt(&v.get_inferred_expr_type(None)),
                if none.is_none() { "N" } else { "R" }.to_string(),
                bounds(r.get_lower_bounds()),
                bounds(r.get_upper_bounds()),
            ],
        ));
    }

    reset();
    let empty = NewExprent::new(VarType::new_dim(CodeType::Int, 1), Vec::new(), None);
    empty.set_direct_array_init(true);
    actual.push(line(
        "new_direct_empty",
        &[
            text(empty.0),
            hex(&empty.get_lambda_method_key()),
            hex(&empty.get_lambda_content_method_key()),
            b(empty.does_class_have_methods_named_same()).to_string(),
            vt(&empty.get_inferred_expr_type(None)),
            b(empty.is_anonymous()).to_string(),
        ],
    ));

    reset();
    let dims = vec![ConstExprent::new_int(3, false, None).0];
    let ints = NewExprent::new(VarType::new_dim(CodeType::Int, 1), dims, None);
    ints.set_lst_array_elements(vec![
        ConstExprent::new_int(1, true, None).0,
        ConstExprent::new_int(2, false, None).0,
    ]);
    let r = ints.check_expr_type_bounds().expect("result");
    actual.push(bounds_line("int1", &r));

    reset();
    let strs = NewExprent::new(
        VarType::new_value(CodeType::Object, 1, "java/lang/String"),
        Vec::new(),
        None,
    );
    strs.set_lst_array_elements(vec![
        ConstExprent::new(VarType::VARTYPE_NULL(), None, None).0,
    ]);
    let r = strs.check_expr_type_bounds().expect("result");
    actual.push(bounds_line("str1", &r));

    reset();
    let dims2 = vec![
        ConstExprent::new_int(2, false, None).0,
        ConstExprent::new_int(4, false, None).0,
    ];
    let grid = NewExprent::new(VarType::new_dim(CodeType::Long, 2), dims2, None);
    grid.set_lst_array_elements(vec![
        ConstExprent::new(VarType::VARTYPE_NULL(), None, None).0,
    ]);
    let r = grid.check_expr_type_bounds().expect("result");
    actual.push(bounds_line("long2", &r));

    reset();
    let obj = NewExprent::new(
        VarType::new_value(CodeType::Object, 0, "java/lang/Object"),
        Vec::new(),
        None,
    );
    let r = obj.check_expr_type_bounds().expect("result");
    actual.push(bounds_line("obj0", &r));

    let expected: Vec<&str> = GOLDEN.lines().collect();
    let mut mismatches = Vec::new();
    for i in 0..expected.len().max(actual.len()) {
        let e = expected.get(i).copied().unwrap_or("<missing>");
        let a = actual.get(i).map(String::as_str).unwrap_or("<missing>");
        if e != a {
            mismatches.push(format!("java: {e}\nrust: {a}"));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}
